import{I as p,o as t,c as o,b6 as n,J as r,w as h,j as s,a as l}from"./chunks/framework.BUXTSoD9.js";const k=JSON.parse('{"title":"Jobs to Be Done でユーザーが本当に達成したいことを見極める","description":"ゼロベースの読者向けの Jobs to Be Done 入門記事。ユーザーは機能を買っているのではなく、特定のシーンでプロダクトを「雇用」して進捗を達成していることを理解し、JTBD でプロダクト方向、インタビュー質問、AI プロンプトを分解する方法を学びます。","frontmatter":{"title":"Jobs to Be Done でユーザーが本当に達成したいことを見極める","description":"ゼロベースの読者向けの Jobs to Be Done 入門記事。ユーザーは機能を買っているのではなく、特定のシーンでプロダクトを「雇用」して進捗を達成していることを理解し、JTBD でプロダクト方向、インタビュー質問、AI プロンプトを分解する方法を学びます。"},"headers":[],"relativePath":"ja-jp/stage-1/appendix-jobs-to-be-done/index.md","filePath":"ja-jp/stage-1/appendix-jobs-to-be-done/index.md"}'),d={name:"ja-jp/stage-1/appendix-jobs-to-be-done/index.md"},_=Object.assign(d,{setup(c){const i="約 <strong>1.5 時間</strong>";return(b,a)=>{const e=p("ChapterIntroduction");return t(),o("div",null,[a[1]||(a[1]=n('<h1 id="jobs-to-be-done-でユーザーが本当に達成したいことを見極める" tabindex="-1">Jobs to Be Done でユーザーが本当に達成したいことを見極める <a class="header-anchor" href="#jobs-to-be-done-でユーザーが本当に達成したいことを見極める" aria-label="Permalink to “Jobs to Be Done でユーザーが本当に達成したいことを見極める”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="本章のガイド" tabindex="-1">本章のガイド <a class="header-anchor" href="#本章のガイド" aria-label="Permalink to “本章のガイド”">​</a></h2>',3)),r(e,{duration:i,tags:["JTBD","ユーザーニーズ","プロダクト思考","ニーズインサイト"],coreOutput:"1 つのよりリアルなニーズに近い JTBD 文",expectedOutput:"曖昧なアイデアをより具体的なユーザーシーンと MVP 方向に絞り込める"},{default:h(()=>[...a[0]||(a[0]=[s("p",null,"多くの人が初めてプロダクトを作る時、最も陥りやすい間違いは「自分がどんな機能を作るか」に注意を全部向けてしまうことです。他のプロダクトにスマート分類があれば自分も追加したくなり、自動サマリーがあれば自分も接続したくなり、Agent、マルチモーダル、ワークフローがあれば自分も欠かせないと感じてしまいます。",-1),s("p",null,"しかし現実には、ユーザーが「この機能名がかっこいいから」という理由でプロダクトを使うことはめったにありません。彼らはむしろ特定の場面で、あることを前に進めたいと思い、一時的にツールやサービス、さらには人を「雇用」して、この一歩を完了させようとします。",-1),s("p",null,[l("これこそが "),s("strong",null,"Jobs to Be Done（JTBD）"),l(" という手法が私たちに気づかせようとしていることです："),s("strong",null,"ユーザーは機能そのものを買っているのではなく、あるソリューションを雇用して、自分の進捗を達成しようとしているのです。")],-1),s("p",null,"本記事はできるだけ分かりやすい言葉で、ゼロから JTBD を理解し、AI アプリケーションを作る際に直接使える分析ツールにするまでを案内します。",-1)])]),_:1}),a[2]||(a[2]=n(`<div class="info custom-block"><p class="custom-block-title">最小 SOP</p><p><strong>目的</strong>：読み終わった後、曖昧なアイデアを本当にユーザーシーンのあるニーズの一文に絞り込む方法がより明確になり、頭の中に機能名の羅列だけが残ることはありません。</p><p><strong>アクション項目</strong>：曖昧なアイデアを 1 文書き、潜在ユーザー 3 人に「前回どう対処したか」を聞き、それを JTBD 文に整理する。</p><p><strong>結果</strong>：より明確なニーズ仮説が得られ、初版で何を優先すべきかがわかる。</p><p><strong>キーワードジャンプ</strong>：<a href="#jtbd-what">JTBDとは</a> · <a href="#jtbd-formula">一文公式</a> · <a href="#jtbd-ai">AIの活用法</a></p></div><h2 id="この章で学ぶ内容" tabindex="-1">この章で学ぶ内容 <a class="header-anchor" href="#この章で学ぶ内容" aria-label="Permalink to “この章で学ぶ内容”">​</a></h2><ol><li>Jobs to Be Done とは何か、なぜ「機能ブレスト」よりもリアルなニーズに近いのか</li><li>「ユーザーが欲しいと言う機能」と「ユーザーが本当に達成したいこと」の区別方法</li><li>簡単なテンプレートを使って、曖昧なアイデアをシーン、トリガー、障害、成功基準に分解する方法</li><li>JTBD を AI プロダクト、インタビュー質問、プロンプト整理にどう活用するか</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-jobs-to-be-done-とは何か" tabindex="-1"><a href="#top-jtbd">1. Jobs to Be Done とは何か</a> <a class="header-anchor" href="#_1-jobs-to-be-done-とは何か" aria-label="Permalink to “1. Jobs to Be Done とは何か”">​</a></h2><p>Jobs to Be Done は <strong>JTBD</strong> と略されることが多いです。その背後にある核心的なアイデアは、Clayton Christensen のチームが広めた次の古典的な表現に関連しています：<strong>ユーザーはあるプロダクトを「雇用」して一つのことを完了させる。</strong></p><p>ここで言う「こと」とは、ToDoリストにあるような表面的な動作ではなく、ユーザーが自分の状態を変えたいと思う一種の <strong>進捗</strong> です。例えば：</p><ul><li>「AI 議事録ツールが欲しい」ではなく、「会議後 10 分以内に要点、ToDo、責任者を整理し、もう思い出しながらメモを補完したくない」</li><li>「家計簿 App が欲しい」ではなく、「お金がどこに消えているのかを知りたい、月末に不安を感じたくない」</li><li>「履歴書最適化ツールが欲しい」ではなく、「安心してまともな履歴書を提出したい、毎回提出するたびに自分の書いたものが不十分だと疑いたくない」</li></ul><p>だから、<strong>JTBD が注目するのはプロダクトがどう見えるかではなく、ユーザーがなぜこの瞬間にそれを必要としているのかです。</strong></p><p>これこそが、一見異なるプロダクトが実際には同じ Job を争っている理由でもあります。ユーザーが「通勤途中で退屈したくない」と思えば、雇用の対象はショート動画、ポッドキャスト、ゲーム、チャット、さらには居眠りかもしれません。ユーザーが「とても長い PDF を素早く理解したい」と思えば、雇用の対象は AI 要約ツール、インターン、同僚、自分で頑張って読む、あるいはとりあえず読まないことかもしれません。</p><p>この視点で問題を見ると、本当の競合相手は「自分と似たような App」だけではなく、<strong>ユーザーの現在受け入れ可能なすべての代替ソリューション</strong> であることに気づくでしょう。</p><h2 id="_2-jtbd-とユーザーペルソナ、機能リストの違い" tabindex="-1">2. JTBD とユーザーペルソナ、機能リストの違い <a class="header-anchor" href="#_2-jtbd-とユーザーペルソナ、機能リストの違い" aria-label="Permalink to “2. JTBD とユーザーペルソナ、機能リストの違い”">​</a></h2><p>多くの初心者が初めてニーズ分析をする時、まずユーザーペルソナを書きます：25 歳、女性、一線都市、ホワイトカラー、効率ツールが好き、新しいプロダクトを試す意欲がある。この情報は全く役に立たないわけではありませんが、通常 <strong>一人がなぜこの瞬間に行動を起こすのかを説明するのには不十分です。</strong></p><p>JTBD がより関心を持つのは次のような問題です：</p><ul><li>どんなシーンでソリューションを探すことを決めたのか</li><li>その時、何につまずいたのか</li><li>何を次のステップに進めたいのか</li><li>今どんな不器用な方法でやりくりしているのか</li><li>もし上手く解決できたら、どんな結果なら「価値があった」と思うのか</li></ul><p>つまり、<strong>ユーザーペルソナは「この人が大体誰か」に近く、JTBD は「この人が今本当に何を達成したいか」に近い</strong> ということです。</p><p>同様に、機能リストも人を誤導しがちです。ユーザーが「Word エクスポートが欲しい」「AI リライトが欲しい」「音声入力が欲しい」と言っても、これらは表面的な表現にすぎません。JTBD はさらに掘り下げます：</p><ul><li>なぜ今 PDF ではなく Word でエクスポートする必要があるのか？</li><li>リライトしたいのは、文章のスタイルが良くないからか、それとも異なる対象に合わせる必要があるからか？</li><li>音声入力が欲しいのは、タイプするのが面倒だからか、それとも歩いている時、運転している時、会議直後にすぐ記録するからか？</li></ul><p>多くの場合、<strong>機能は Job の一時的な翻訳にすぎません</strong>。機能だけを集めると、プロダクトは「ユーザーが言うままに積み上げる」ものになりがちですが、背後にある Job が見えれば、本当に使いやすく、本当に競争力のあるソリューションを作れる可能性がずっと高くなります。</p><h2 id="_3-ゼロベースでも理解できる例" tabindex="-1">3. ゼロベースでも理解できる例 <a class="header-anchor" href="#_3-ゼロベースでも理解できる例" aria-label="Permalink to “3. ゼロベースでも理解できる例”">​</a></h2><p>まず複雑な AI プロダクトを考えるのは後回しにして、生活の例から始めましょう。</p><p>ある人が朝出かける前にいつも朝食を食べる時間がなく、よく地下鉄の入り口でサンドイッチとコーヒーを買うと仮定します。表面的には彼は「朝食」を「購入」していますが、JTBD で見れば、彼が本当に達成したいことは：</p><ul><li>急いでいる朝に、最も頭を使わない方法で一食を済ませる</li><li>会社に着く前に空腹でフラフラにならない</li><li>朝食のために通勤のペースを崩さない</li></ul><p>この時、ユーザーが雇用しているのは「ある特定ブランドのサンドイッチ」ではなく、朝をスムーズに進められるソリューションです。隣のコンビニがより速く、より近く、より安定していれば、彼はすぐに元の選択を変えるかもしれません。</p><p>このロジックを AI プロダクトに持ち込むと、より明白になります。</p><p>例えば「AI 議事録ツール」を作りたいとします。機能のレベルに留まると、すぐに考え始めがちです：</p><ul><li>音声アップロードに対応すべきか</li><li>話者分離に対応すべきか</li><li>Markdown エクスポートに対応すべきか</li><li>自動 ToDo 生成に対応すべきか</li></ul><p>これらは間違いではありませんが、まだ不十分です。JTBD でもう一段階問い直すと、ユーザーが本当に達成したいのは：</p><ul><li>会議後 10 分以内に、議論結果を不参加者に同期したい</li><li>ToDo、責任者、締切をきれいに抽出し、チームが記憶に頼ったコラボレーションをしなくて済むようにしたい</li><li>議事録の整理にかかる繰り返しの時間を減らし、意思決定と実行にエネルギーを注ぎたい</li></ul><p>Job が明確になると、多くの機能の優先順位が自動的に見えてきます。初版で最も重要なのは「12 種類のエクスポート形式に対応すること」ではなく、次のようなことかもしれません：</p><ul><li>議事録の構造が十分に明確であること</li><li>ToDo 抽出が安定していること</li><li>共有リンクが便利であること</li><li>出力結果がチームに直接転送できる信頼性があること</li></ul><p>これこそが JTBD の価値です：<strong>「どの能力を積み上げるか」から「ユーザーのどんな進捗を支援するか」に注意を戻すことができます。</strong></p><h2 id="_4-使いやすい-jtbd-テンプレート" tabindex="-1">4. 使いやすい JTBD テンプレート <a class="header-anchor" href="#_4-使いやすい-jtbd-テンプレート" aria-label="Permalink to “4. 使いやすい JTBD テンプレート”">​</a></h2><p>ゼロベースなら、JTBD を学術的に考えすぎる必要はありません。まず最も実用的な 5 つの要素を掴めば十分です。</p><h3 id="_4-1-シーン" tabindex="-1">4.1 シーン <a class="header-anchor" href="#_4-1-シーン" aria-label="Permalink to “4.1 シーン”">​</a></h3><p>ユーザーはどんな瞬間、どんな環境でこのプロダクトを思い出すのか？</p><ul><li>会議が終わった後</li><li>上司が急に資料を求めてきた時</li><li>夜履歴書を提出する準備をしている時</li><li>月末にお金がまた足りないことに気づいた時</li></ul><p><strong>シーンのないニーズは、通常まだリアルではありません。</strong></p><h3 id="_4-2-トリガー" tabindex="-1">4.2 トリガー <a class="header-anchor" href="#_4-2-トリガー" aria-label="Permalink to “4.2 トリガー”">​</a></h3><p>何が彼にすぐソリューションを探す決意をさせたのか？</p><ul><li>長い文書に圧倒され、どこから読めばいいかわからない</li><li>明日提出の資料が、今日になってフォーマットがめちゃくちゃだと気づく</li><li>上司に進捗を追及され、自分が整理しきれていないことに気づく</li><li>記録を続けたいが、手書き、コピー、整理が面倒すぎる</li></ul><p>トリガーには往々にして感情が伴います。この感情は重要です。なぜなら、ユーザーがなぜこの瞬間に行動を起こすのかを決めるからです。</p><h3 id="_4-3-達成したい進捗" tabindex="-1">4.3 達成したい進捗 <a class="header-anchor" href="#_4-3-達成したい進捗" aria-label="Permalink to “4.3 達成したい進捗”">​</a></h3><p>彼は「一つの動作をする」だけでなく、自分をどんな新しい状態に進めたいのか？</p><ul><li>混乱から明確へ</li><li>不安から安心へ</li><li>先延ばしからスタートへ</li><li>非効率からスムーズへ</li><li>うまく説明できないから直接届けられるものへ</li></ul><p>このステップで「進捗」という言葉が非常に重要です。なぜなら、多くの人が本当に買っているのはツールではなく、<strong>状態の変化</strong> だからです。</p><h3 id="_4-4-現在の代替ソリューション" tabindex="-1">4.4 現在の代替ソリューション <a class="header-anchor" href="#_4-4-現在の代替ソリューション" aria-label="Permalink to “4.4 現在の代替ソリューション”">​</a></h3><p>あなたのプロダクトがない今、彼はどうしているのか？</p><ul><li>手作業でコピペ</li><li>Excel やメモアプリでやりくり</li><li>同僚に頼る</li><li>先延ばしにする</li><li>複数のツールの間で行き来する</li></ul><p>誰が代替ソリューションか、誰があなたの本当の競争環境か。</p><h3 id="_4-5-成功基準" tabindex="-1">4.5 成功基準 <a class="header-anchor" href="#_4-5-成功基準" aria-label="Permalink to “4.5 成功基準”">​</a></h3><p>どうなったら本当に解決したと言えるのか？</p><ul><li>10 分以内に共有可能な結果が得られる</li><li>大きな修正なしで他人に送れる</li><li>抜け漏れ、ミス、忘れが起こりにくい</li><li>初めて使っても次のステップがわかる</li></ul><p>「ユーザーがどうやって価値を判断するか」すら言えないなら、その方向性はおそらくまだ十分に絞り込まれていません。</p><p><a id="jtbd-formula"></a></p><h2 id="_5-そのまま使える一文公式" tabindex="-1"><a href="#top-jtbd">5. そのまま使える一文公式</a> <a class="header-anchor" href="#_5-そのまま使える一文公式" aria-label="Permalink to “5. そのまま使える一文公式”">​</a></h2><p>プロダクトの方向性を整理したい時、まずこの実用的なテンプレートに当てはめてみてください：</p><blockquote><p>__________ の時、__________ がしたい、それは __________ のためだ。 今は __________ でなんとかこのことをやり遂げている。</p></blockquote><p>例えば：</p><blockquote><p>情報量が多いプロジェクト会議が終わった時、ToDo、責任者、締切を含む議事録を素早く得て、すぐにチームに同期し実行を推進したい。 今は自分の記憶、チャット履歴の確認、手作業での整理でなんとかやり遂げている。</p></blockquote><p>もう一つの例：</p><blockquote><p>新しい職種に応募する準備をする時、既存の経歴を職種に合ったバージョンに素早く書き換えて、安心してまともな履歴書を提出したい。 今は古い履歴書を繰り返しコピペし、言葉を手作業で修正し、最後にはどんどん自信がなくなっている。</p></blockquote><p>一文をこの明確さまで書ければ、その後の画面設計、プロンプト設計、機能優先度の判断がずっと楽になります。</p><h2 id="_6-ai-プロダクトを作る時、特に注目すべき-3-つのレイヤーの-job" tabindex="-1">6. AI プロダクトを作る時、特に注目すべき 3 つのレイヤーの Job <a class="header-anchor" href="#_6-ai-プロダクトを作る時、特に注目すべき-3-つのレイヤーの-job" aria-label="Permalink to “6. AI プロダクトを作る時、特に注目すべき 3 つのレイヤーの Job”">​</a></h2><p>多くの AI プロダクトは機能デモでは強そうに見えますが、実際にリリースされてもユーザーが定着しないことがよくあります。その一般的な理由は、表面的な動作を解決しただけで、より深い Job を解決していないからです。</p><p>Job は大まかに 3 つのレイヤーに分けて見ることができます：</p><h3 id="_6-1-機能レイヤー" tabindex="-1">6.1 機能レイヤー <a class="header-anchor" href="#_6-1-機能レイヤー" aria-label="Permalink to “6.1 機能レイヤー”">​</a></h3><p>最も表面的なタスクは何か？</p><ul><li>文書の要約</li><li>コピーのリライト</li><li>ToDo の抽出</li><li>画像の生成</li></ul><p>これはユーザーが口に出しやすいレイヤーです。</p><h3 id="_6-2-感情レイヤー" tabindex="-1">6.2 感情レイヤー <a class="header-anchor" href="#_6-2-感情レイヤー" aria-label="Permalink to “6.2 感情レイヤー”">​</a></h3><p>ユーザーはどんな不快感を減らしたいのか、またはどんな感情を得たいのか？</p><ul><li>慌てたくない</li><li>プロフェッショナルに見えたい</li><li>毎回ゼロから始めたくない</li><li>コントロール感が欲しい</li></ul><p>多くの有料意欲は、実際に感情レイヤーと深く関係しています。</p><h3 id="_6-3-社会レイヤー" tabindex="-1">6.3 社会レイヤー <a class="header-anchor" href="#_6-3-社会レイヤー" aria-label="Permalink to “6.3 社会レイヤー”">​</a></h3><p>ユーザーは他人の目にどうなりたいのか？</p><ul><li>より頼りに見られたい</li><li>チームでより組織力があると思われたい</li><li>顧客の前でよりプロフェッショナルに見られたい</li><li>SNS でより表現力があると思われたい</li></ul><p>機能レイヤーだけをやっていれば、プロダクトは代替されやすいです。感情レイヤーと社会レイヤーも同時に理解すれば、より粘着性のある価値を見つけやすくなります。</p><h2 id="_7-jtbd-を逆に使ってプロダクト方向を絞り込む" tabindex="-1">7. JTBD を逆に使ってプロダクト方向を絞り込む <a class="header-anchor" href="#_7-jtbd-を逆に使ってプロダクト方向を絞り込む" aria-label="Permalink to “7. JTBD を逆に使ってプロダクト方向を絞り込む”">​</a></h2><p>時にはすでにプロダクトがあるのではなく、3〜5 のアイデアがあって、どれを作るべきかわからないことがあります。この時、JTBD は選別に非常に適しています。</p><p>各アイデアを取り上げて、それぞれに 5 つの質問をすることができます：</p><ol><li>このアイデアに対応するシーンは十分に具体的か？</li><li>ユーザーはすでに何らかの不器用な方法で解決しているか？</li><li>この Job の痛みは十分に強いか、または十分に高頻度か？</li><li>もし上手くできたら、ユーザーは明らかに「状態が良くなった」と感じるか？</li><li>初版はこの Job の重要な一歩だけを囲んで、小さいが有用なバージョンを作れるか？</li></ol><p>ある方向性が最後まで説明しても「面白そう」としか言えず、トリガー、代替ソリューション、成功基準をはっきりと言えないなら、それはおそらくまだ曖昧なインスピレーションであって、成熟した方向性ではありません。</p><h2 id="_8-そのままユーザーインタビューに使える質問" tabindex="-1">8. そのままユーザーインタビューに使える質問 <a class="header-anchor" href="#_8-そのままユーザーインタビューに使える質問" aria-label="Permalink to “8. そのままユーザーインタビューに使える質問”">​</a></h2><p>多くの人は調査をする時、「どんな機能が欲しいですか？」と聞いてしまいます。この聞き方は表面的な回答を得やすいです。</p><p>JTBD は次のような質問により適しています：</p><ul><li>前回この問題に直面したのはいつですか？</li><li>その時何をしていて、なぜつまずいたのですか？</li><li>最終的にどう解決しましたか？</li><li>このプロセスで一番面倒で、一番遅くて、一番不安なのはどこですか？</li><li>もしツールがあれば、どんな結果なら本当に役に立つと思いますか？</li><li>どんな代替方法を試しましたか？なぜ十分ではなかったのですか？</li></ul><p>この聞き方には利点があります：会話をリアルな体験に引き戻し、想像上の好みに留まらせないことです。</p><h2 id="_9-ai-に-jtbd-分析を手伝ってもらう" tabindex="-1">9. AI に JTBD 分析を手伝ってもらう <a class="header-anchor" href="#_9-ai-に-jtbd-分析を手伝ってもらう" aria-label="Permalink to “9. AI に JTBD 分析を手伝ってもらう”">​</a></h2><p>JTBD 自体は AI が発明したものではありませんが、AI は JTBD の整理と洗練に非常に適しています。</p><p>例えば、5〜10 件のユーザーフィードバックを収集したら、それらをモデルに渡して次の構造でまとめてもらうことができます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>プロダクト研究アシスタントを演じてください。</span></span>
<span class="line"><span>ユーザーの生の言葉を渡します。まず機能提案をせず、</span></span>
<span class="line"><span>Jobs to Be Done のフレームワークで整理してください：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. ユーザーはどんなシーンにいるか</span></span>
<span class="line"><span>2. 行動を起こすトリガーは何か</span></span>
<span class="line"><span>3. 本当に達成したい進捗は何か</span></span>
<span class="line"><span>4. 現在の代替ソリューションは何か</span></span>
<span class="line"><span>5. 最も重視する成功基準は何か</span></span>
<span class="line"><span>6. これらのフィードバックで繰り返し出現する感情ワードは何か</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最後に、これらを最も優先的に検証すべき 3 つの JTBD 仮説に整理してください。</span></span></code></pre></div><p>もしすでにアイデアがあるなら、AI に第一段階の絞り込みをしてもらうこともできます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[あなたのプロダクトアイデア] を作りたい。</span></span>
<span class="line"><span>機能リストを直接出すのではなく、Jobs to Be Done の方法で分析してください：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. このプロダクトがサービスする可能性のある具体的なシーンは何か</span></span>
<span class="line"><span>2. 各シーンでユーザーが達成したいコア Job は何か</span></span>
<span class="line"><span>3. 既存の代替ソリューションには何があるか</span></span>
<span class="line"><span>4. どの Job が MVP の出発点として最も適しているか、なぜか</span></span>
<span class="line"><span>5. 最終的に推奨する Job を明確な JTBD 文に書いてください</span></span></code></pre></div><p>このようにすることで、最初から AI に「50 の機能をブレスト」させるのではなく、方向性をまず明確にできます。</p><h2 id="_10-初心者が最も陥りやすい-4-つの誤解" tabindex="-1">10. 初心者が最も陥りやすい 4 つの誤解 <a class="header-anchor" href="#_10-初心者が最も陥りやすい-4-つの誤解" aria-label="Permalink to “10. 初心者が最も陥りやすい 4 つの誤解”">​</a></h2><h3 id="_10-1-job-を機能名にしてしまう" tabindex="-1">10.1 Job を機能名にしてしまう <a class="header-anchor" href="#_10-1-job-を機能名にしてしまう" aria-label="Permalink to “10.1 Job を機能名にしてしまう”">​</a></h3><p>「AI 要約」「スマート分類」「自動生成」は Job ではなく、それらは実現方法の可能性にすぎません。</p><h3 id="_10-2-ターゲット層を広く書きすぎる" tabindex="-1">10.2 ターゲット層を広く書きすぎる <a class="header-anchor" href="#_10-2-ターゲット層を広く書きすぎる" aria-label="Permalink to “10.2 ターゲット層を広く書きすぎる”">​</a></h3><p>「すべてのビジネスパーソン」「すべての学生」「すべての起業家」は通常広すぎます。広ければ広いほど、リアルなシーンを見えなくなります。</p><h3 id="_10-3-ユーザーの言葉だけを聞き、行動を見ない" tabindex="-1">10.3 ユーザーの言葉だけを聞き、行動を見ない <a class="header-anchor" href="#_10-3-ユーザーの言葉だけを聞き、行動を見ない" aria-label="Permalink to “10.3 ユーザーの言葉だけを聞き、行動を見ない”">​</a></h3><p>ユーザーは自分が何を欲しがっているかを説明できますが、彼らの本当の優先順位は、今どのように問題をやりくりしているかに隠されていることが多いです。</p><h3 id="_10-4-最初から完全なプラットフォームを作ろうとする" tabindex="-1">10.4 最初から完全なプラットフォームを作ろうとする <a class="header-anchor" href="#_10-4-最初から完全なプラットフォームを作ろうとする" aria-label="Permalink to “10.4 最初から完全なプラットフォームを作ろうとする”">​</a></h3><p>JTBD の正しい使い方は、通常「何でもできる大きなプラットフォームを作る」ことではなく、まず一つのシーンで最も重要な一歩に注目し、それを非常に使いやすくすることです。</p><h2 id="_11-まとめ" tabindex="-1">11. まとめ <a class="header-anchor" href="#_11-まとめ" aria-label="Permalink to “11. まとめ”">​</a></h2><p>Jobs to Be Done の最も価値のある点は、新しい用語を与えることではなく、観察の角度を変えてくれることです：<strong>プロダクトの機能だけを見るのではなく、ユーザーが何を次のステップに進めたいのかを見る。</strong></p><p>あなたが次のようなことを繰り返し自分に問い始めると：</p><ul><li>ユーザーはどんなシーンでこのプロダクトを雇用しているのか</li><li>彼は一体どこでつまずいているのか</li><li>今どんな方法でやりくりしているのか</li><li>問題が解決した後、状態はどう変わるのか</li></ul><p>元々曖昧だったアイデアが急にはっきりとし、元々派手だった機能も急に重要ではなくなっていくことに気づくでしょう。</p><p>プロダクトを作る時、特に AI プロダクトを作る時、最も怖しいのは最初から能力展示に夢中になることです。JTBD はあなたの注意を本当に重要なところに引き戻してくれます：<strong>ユーザーはなぜあなたを必要としているのか、そしてあなたは一体ユーザーのどんな進捗を支援しているのか。</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-ai-を活用して-jtbd-を実践する方法" tabindex="-1"><a href="#top-jtbd">12. AI を活用して JTBD を実践する方法</a> <a class="header-anchor" href="#_12-ai-を活用して-jtbd-を実践する方法" aria-label="Permalink to “12. AI を活用して JTBD を実践する方法”">​</a></h2><p>JTBD は AI が発明したものではありませんが、AI はこの手法で研究アシスタント、整理アシスタント、対照アシスタントとして非常に適しています。重要なのは：<strong>AI に整理と拡張をさせ、ユーザーの推測をAIに代行させないこと。</strong></p><p>次のように活用できます：</p><h3 id="_12-1-ai-に曖昧なアイデアを-jtbd-仮説に書き直させる" tabindex="-1">12.1 AI に曖昧なアイデアを JTBD 仮説に書き直させる <a class="header-anchor" href="#_12-1-ai-に曖昧なアイデアを-jtbd-仮説に書き直させる" aria-label="Permalink to “12.1 AI に曖昧なアイデアを JTBD 仮説に書き直させる”">​</a></h3><p>頭の中に「大学生のインターン探しを支援するツールを作りたい」という曖昧な説明しかない時、まず AI にそれをいくつかの可能性のある Job に分解させることができます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>今、曖昧なプロダクトアイデアがあります：[あなたのアイデア]</span></span>
<span class="line"><span>機能リストを直接出すのではなく、Jobs to Be Done の方法で分析してください：</span></span>
<span class="line"><span>1. どのような具体的なシーンに対応する可能性があるか</span></span>
<span class="line"><span>2. 各シーンでユーザーが本当に達成したい進捗は何か</span></span>
<span class="line"><span>3. 現在の代替ソリューションは何か</span></span>
<span class="line"><span>4. どの Job を最初に MVP にするのが最も適切か</span></span>
<span class="line"><span>最後に各 Job を明確な JTBD 文に書いてください。</span></span></code></pre></div><p>非常に初心者っぽい入力でも全く問題ありません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>大学生のインターン探しを支援するものを作りたい。</span></span>
<span class="line"><span>具体的に何を作るかまだはっきり言えない。ユーザーが本当に何を達成したいかを考えてみて。</span></span></code></pre></div><p>AI が返す有用な出力は次のようになります：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>可能性のある JTBD 方向：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 初めてインターンに応募する準備をする時、まず何を準備すべきかを素早く知りたい、</span></span>
<span class="line"><span>情報が乱雑で応募を先延ばしにしたくない。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. インターンの求人を見た時、自分が応募する価値があるかどうかを素早く判断したい、</span></span>
<span class="line"><span>不適切な求人に時間を無駄にしたくない。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 応募を始める時、既存の履歴書を求人に合ったバージョンに素早く書き換えたい、</span></span>
<span class="line"><span>より早く応募を完了し、通過率を高めたい。</span></span></code></pre></div><p>このような出力の価値は、元々非常に漠然としていたアイデアを、よりリアルなシーンに近い方向に分解してくれることです。</p><h3 id="_12-2-ai-にインタビューの生の言葉を整理させる" tabindex="-1">12.2 AI にインタビューの生の言葉を整理させる <a class="header-anchor" href="#_12-2-ai-にインタビューの生の言葉を整理させる" aria-label="Permalink to “12.2 AI にインタビューの生の言葉を整理させる”">​</a></h3><p>すでに何度かユーザーインタビューを終えたなら、インタビュー記録を AI に渡して、繰り返し出現するシーン、トリガー、代替ソリューション、成功基準を抽出させることができます。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>以下は 5 人のユーザーのインタビュー生の言葉です。</span></span>
<span class="line"><span>まずソリューションを出さず、JTBD フレームワークで整理してください：</span></span>
<span class="line"><span>1. ユーザーはどんなシーンにいるか</span></span>
<span class="line"><span>2. 行動を起こすトリガーは何か</span></span>
<span class="line"><span>3. 本当に達成したい進捗は何か</span></span>
<span class="line"><span>4. 現在の代替ソリューションは何か</span></span>
<span class="line"><span>5. 最も重視する成功基準は何か</span></span>
<span class="line"><span>6. どの情報が複数のユーザーで繰り返し出現しているか</span></span>
<span class="line"><span>最後に、最も優先的に検証すべき 3 つの JTBD 仮説に整理してください。</span></span></code></pre></div><p>非常にシンプルな初心者入力も次のように書けます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>3 人に聞きました。大体こんな風に言っていました：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 毎回インターンに応募するたびに履歴書を書き直すのが本当に面倒。</span></span>
<span class="line"><span>2. 一番怖いのは、自分が書いたものが正しいかどうかわからないこと。</span></span>
<span class="line"><span>3. 今は先輩に見てもらうようにしているけど、毎回頼むのは申し訳ない。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>彼らが本当に達成したいことを整理して。</span></span></code></pre></div><p>AI は次のように出力するかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>整理結果：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 共通シーン：インターン応募前の履歴書処理</span></span>
<span class="line"><span>- 共通の困難：「十分良い」までどう修正すればいいかわからない</span></span>
<span class="line"><span>- 現在の代替ソリューション：先輩に見てもらう、自分で繰り返し修正</span></span>
<span class="line"><span>- 可能な JTBD：</span></span>
<span class="line"><span>  インターンに応募する準備をする時、履歴書が応募可能なレベルに達しているかをより早く判断したい、</span></span>
<span class="line"><span>  「もう少し修正」でずっと応募できずにいる状況から抜け出したい。</span></span></code></pre></div><p>このような出力は、散らばった生の言葉から「ニーズ」により近いものを抽出してくれるので、非常に有用です。</p><h3 id="_12-3-ai-に軽量なウェブ調査を先に行わせる" tabindex="-1">12.3 AI に軽量なウェブ調査を先に行わせる <a class="header-anchor" href="#_12-3-ai-に軽量なウェブ調査を先に行わせる" aria-label="Permalink to “12.3 AI に軽量なウェブ調査を先に行わせる”">​</a></h3><p>大規模なインタビューを始める前に、AI に少し軽い外部情報スキャンをさせることができます。例えば：</p><ul><li>公開フォーラムやコミュニティで、皆がこの問題にどう不満を漏らしているか</li><li>市場の既存プロダクトが主にどのレベルの問題を解決しているか</li><li>ユーザーの最も一般的な代替ソリューションは何か</li><li>一般的な評価で、最も満足されている点と最も不満な点は何か</li></ul><p>この調査はリアルなユーザーインタビューに代わるものではありませんが、Discover 段階のウォームアップとして、問題の地図を先に構築するのに非常に適しています。</p><p>シンプルな入力は次のようなものです：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>調べてほしいことがあります：</span></span>
<span class="line"><span>「大学生が履歴書を修正してインターンに応募する時、最もよくあるペインポイントは何？」</span></span>
<span class="line"><span>公開フォーラム、経験談、就職コミュニティで皆が自分で言っていることを優先的に見てください。</span></span>
<span class="line"><span>最も一般的な問題を 5 つに整理して。</span></span></code></pre></div><p>AI は次のように出力するかもしれません：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>よくあるペインポイントの整理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 履歴書に何を書けばいいかわからない、経歴が少なすぎる</span></span>
<span class="line"><span>2. 異なる職種に合わせてどう修正すればいいかわからない</span></span>
<span class="line"><span>3. 何度も修正したが、まだ十分かどうかわからない</span></span>
<span class="line"><span>4. 信頼できる人に見てもらえない</span></span>
<span class="line"><span>5. 応募プロセスが複雑で、先延ばしにしがち</span></span></code></pre></div><p>この種の出力は最終結論として扱うべきではありませんが、どの問題を優先してインタビューするかを決めるのに非常に適しています。</p><h3 id="_12-4-ai-に「反論者」を演じさせる" tabindex="-1">12.4 AI に「反論者」を演じさせる <a class="header-anchor" href="#_12-4-ai-に「反論者」を演じさせる" aria-label="Permalink to “12.4 AI に「反論者」を演じさせる”">​</a></h3><p>多くの場合、私たちは自分のアイデアに感情を入れすぎてしまいます。意図的に AI に批判者を演じさせ、問題をより明確に説明するよう促すことができます：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>非常に厳しいプロダクト研究コンサルタントを演じてください。</span></span>
<span class="line"><span>以下は私の JTBD 仮説です：[あなたの仮説]</span></span>
<span class="line"><span>次の観点から批判してください：</span></span>
<span class="line"><span>1. このシーンは広すぎないか</span></span>
<span class="line"><span>2. この Job は機能であり、本当に進捗であるかどうか</span></span>
<span class="line"><span>3. 代替ソリューションが弱すぎないか</span></span>
<span class="line"><span>4. 成功基準が不明確ではないか</span></span>
<span class="line"><span>5. この仮説で最も検証が必要なリスクは何か</span></span></code></pre></div><p>このようにすることで、自分がニーズを見ているのか、それともただ自分が好きなソリューションを見ているのかをより早く発見できます。</p><h2 id="📚-課題" tabindex="-1">📚 課題 <a class="header-anchor" href="#📚-課題" aria-label="Permalink to “📚 課題”">​</a></h2><p>上記の内容に基づいて、次の課題を完了してください：</p><ol><li>最近やりたいプロダクトアイデアを一つ選び、JTBD 公式の一文で明確に書く</li><li>このアイデアに 5 つの要素を補完する：シーン、トリガー、進捗、代替ソリューション、成功基準</li><li>潜在ユーザー 3 人に聞き、「前回この問題に直面したのはいつですか」を少なくとも 1 回は聞き出す</li><li>インタビューの生の言葉を AI に渡し、最も優先的に検証すべき 3 つの JTBD 仮説に整理する</li></ol><h2 id="さらに学ぶために" tabindex="-1">さらに学ぶために <a class="header-anchor" href="#さらに学ぶために" aria-label="Permalink to “さらに学ぶために”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{k as __pageData,_ as default};
